package connector
import("context";"encoding/json";"io";"net/http";"strings";"testing")
func TestLexOpenStagedMetadataDropboxExactQueryLimitAndFilenameOnly(t *testing.T){old:=httpDo;defer func(){httpDo=old}();for _,act:=range []string{"list","search"}{calls:=0;httpDo=func(r *http.Request)(*http.Response,error){calls++;var b map[string]any;json.NewDecoder(r.Body).Decode(&b);if act=="search"{o,_:=b["options"].(map[string]any);if b["query"]!="pdf"||o["max_results"]!=float64(5)||o["filename_only"]!=true||len(o["file_extensions"].([]any))!=1||o["file_extensions"].([]any)[0]!="pdf"||r.URL.String()!="https://api.dropboxapi.com/2/files/search_v2"{t.Fatal("wrong exact query/options")}}else if b["limit"]!=float64(5)||b["path"]!=""{t.Fatal("list exceeded approved page limit")};field:="entries";if act=="search"{field="matches"};return &http.Response{StatusCode:200,Body:io.NopCloser(strings.NewReader(`{"`+field+`":[]}`))},nil};c,e:=Build("dropbox",Settings{"token":"fixture","oauth_lexopen_cloud_files":"v1"},"");if e!=nil{t.Fatal(e)};a:=map[string]any{"action":act,"limit":"5"};if act=="search"{a["query"]="pdf"};out,e:=c.Call(LexOpenMetadataStageContext(context.Background()),a);if e!=nil||!LexOpenValidateMetadataResult("dropbox",act,out)||calls!=1{t.Fatal("metadata request failed")}}}
func TestLexOpenStagedMetadataProjectionRejectsUnsafeOrFileClaims(t *testing.T){valid:=`{"schema":"lexopen-cloud-metadata.v1","service":"dropbox","action":"search","items":[{"kind":"folder","name":"folder.pdf"}],"page_only":true,"exhaustive":false,"items_truncated":false}`;if !LexOpenValidateMetadataResult("dropbox","search",valid){t.Fatal("valid folder metadata rejected")};for _,bad:=range []string{strings.Replace(valid,`"kind":"folder"`,`"kind":"folder","size":5`,1),strings.Replace(valid,`"name":"folder.pdf"`,`"name":"folder.pdf","url":"https://evil.invalid"`,1),strings.Replace(valid,`"exhaustive":false`,`"exhaustive":true`,1),strings.Replace(valid,`"dropbox"`,`"microsoft-365"`,1),`{"state":"desktop_verified"}`}{if LexOpenValidateMetadataResult("dropbox","search",bad){t.Fatal("unsafe metadata accepted")}}}
